    // Finds the minimum and maximum horizontal distance in
    // the tree
    static void findMinMax(Node node, int[] min, int[] max,
                           int hd)
    {
        if (node == null)
            return;

        if (hd < min[0])
            min[0] = hd;
        else if (hd > max[0])
            max[0] = hd;

        // Recur for left and right subtrees
        findMinMax(node.left, min, max, hd - 1);
        findMinMax(node.right, min, max, hd + 1);
    }

    // Collects all nodes at a given vertical distance in
    // level-order
    static void collectVerticalLine(Node root, int dist,
                                    ArrayList<Integer> line)
    {
        int hd = 0;

        // Queue for level-order traversal
        Queue<ArrayList<Object> > q = new LinkedList<>();
        ArrayList<Object> first = new ArrayList<>();
        first.add(root);
        first.add(hd);
        q.add(first);

        while (!q.isEmpty()) {
            ArrayList<Object> curr = q.poll();
            Node node = (Node)curr.get(0);
            hd = (int)curr.get(1);

            if (hd == dist)
                line.add(node.data);

            if (node.left != null) {
                ArrayList<Object> leftNode
                    = new ArrayList<>();
                leftNode.add(node.left);
                leftNode.add(hd - 1);
                q.add(leftNode);
            }
            if (node.right != null) {
                ArrayList<Object> rightNode
                    = new ArrayList<>();
                rightNode.add(node.right);
                rightNode.add(hd + 1);
                q.add(rightNode);
            }
        }
    }

