                           ref int max, int hd)
    {
        if (node == null)
            return;

        if (hd < min)
            min = hd;
        else if (hd > max)
            max = hd;

        // Recur for left and right subtrees
        findMinMax(node.left, ref min, ref max, hd - 1);
        findMinMax(node.right, ref min, ref max, hd + 1);
    }

    // Collects all nodes at a given vertical distance in
    // level-order
    static void collectVerticalLine(Node root, int dist,
                                    List<int> line)
    {
        int hd = 0;

        // Create a queue for level order traversal
        Queue<(Node, int)> q = new Queue<(Node, int)>();
        q.Enqueue((root, 0));

        while (q.Count > 0) {
            var curr = q.Dequeue();
            Node node = curr.Item1;
            hd = curr.Item2;

            if (hd == dist)
                line.Add(node.data);

            if (node.left != null)
                q.Enqueue((node.left, hd - 1));
            if (node.right != null)
                q.Enqueue((node.right, hd + 1));
        }
    }

