class GFG {

    // Performs DFS to map each node to its horizontal
    // distance and level
    static ArrayList<ArrayList<Integer> >
    verticalOrder(Node root)
    {
        TreeMap<Integer, ArrayList<ArrayList<Integer> > >
            map = new TreeMap<>();

        dfs(root, 0, 0, map);
        ArrayList<ArrayList<Integer> > res
            = new ArrayList<>();

        for (int hd : map.keySet()) {
            ArrayList<ArrayList<Integer> > lines
                = map.get(hd);

            // Sorting based on level (2nd element in list)
            Collections.sort(lines, Comparator.comparingInt(
                                        a -> a.get(1)));

            ArrayList<Integer> line = new ArrayList<>();
            for (ArrayList<Integer> node : lines) {

                // add only value, not level
                line.add(node.get(0));
            }
            res.add(line);
        }

        return res;
    }

